<?php// exit if uninstall is not calledif ( !defined( 'WP_UNINSTALL_PLUGIN' ) ) {	exit();}$cookies_bar_keep = get_option( 'vswc-setting-1' );if ( $cookies_bar_keep != 'yes' ) {	// set global	global $wpdb;	// delete options	$wpdb->query( "DELETE FROM {$wpdb->options} WHERE option_name LIKE 'cookies-bar-setting%'" );}